// Mapping des labels
const labelMap = {
  "Syndic": "Label_1107215070567604782",
  "Gestion locative": "Label_1151885618813199628",
  "Essentielles": "Label_255864265859626501",
  "Personal": "Label_3",
  "Receipts": "Label_4",
  "A traiter urgent": "Label_4938988077910989456",
  "Factures Carrefour": "Label_5180827763194058448",
  "Work": "Label_6",
  "Factures Rouen": "Label_6071725231057128983",
  "Blog": "Label_659885575819992047",
  "ID": "Label_7",
  "OVH": "Label_7296642557858161401",
  "Suivi livraison Pichet": "Label_7692245440759375862",
  "A traiter (non urgent)": "Label_8411510230508964137",
  "Blog/Commentaires ebook": "Label_8625761150509488262",
  "Factures Camille": "Label_8963688369978048774"
};

// Récupérer la réponse de Claude
let response = $json.output || $json.response || $json.text || $json;

// Si c'est un objet avec "output", extraire output
if (typeof response === 'object' && response.output) {
  response = response.output;
}

// Convertir en string si nécessaire
response = String(response);

// Si c'est "null" ou vide, skip
if (response.trim() === 'null' || response.trim() === '') {
  return { json: { skip: true } };
}

// Extraire le JSON (chercher {"label":"..."})
const jsonMatch = response.match(/\{"label"\s*:\s*"([^"]+)"\}/);

if (!jsonMatch) {
  // Si pas de match, logger et utiliser défaut
  console.log('Pas de JSON trouvé, réponse brute:', response);
  return {
    json: {
      id: $('Code in JavaScript').item.json.id,
      addLabelIds: ["Label_255864265859626501"], // Essentielles par défaut
      removeLabelIds: []
    }
  };
}

const labelName = jsonMatch[1];
const labelId = labelMap[labelName];

if (!labelId) {
  throw new Error('Label inconnu : ' + labelName);
}

// Récupérer les infos de l'email
const emailId = $('Code in JavaScript').item.json.id;
const currentLabels = $('Code in JavaScript').item.json.labelIds || [];

// Labels à retirer (tous sauf Traités et le nouveau)
const labelsARetirer = currentLabels.filter(label => 
  label.startsWith('Label_') && 
  label !== 'Label_6701427935417109792' &&
  label !== labelId
);

return {
  json: {
    id: emailId,
    addLabelIds: [labelId],
    removeLabelIds: labelsARetirer
  }
};

