// Fonction pour nettoyer le HTML
function cleanHtmlContent(html) {
  if (!html) return '';

  return html
    .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '')
    .replace(/<style\b[^<]*(?:(?!<\/style>)<[^<]*)*<\/style>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&agrave;/g, 'à')
    .replace(/&eacute;/g, 'é')
    .replace(/&egrave;/g, 'è')
    .replace(/&ecirc;/g, 'ê')
    .replace(/&icirc;/g, 'î')
    .replace(/&ocirc;/g, 'ô')
    .replace(/&ucirc;/g, 'û')
    .replace(/&ccedil;/g, 'ç')
    .replace(/\s+/g, ' ')
    .trim();
}

// Traiter les items
return $input.all().map(item => {
  const htmlContent = item.json.html || item.json.body || '';
  const cleanedText = cleanHtmlContent(htmlContent);

  return {
    json: {
      id: item.json.id,
      from: item.json.from?.value?.[0]?.address || item.json.from,
      from_name: item.json.from?.value?.[0]?.name || '',
      subject: item.json.subject || '',
      labelIds: item.json.labelIds || [],
      date: item.json.date,
      extrait: cleanedText.substring(0, 2000) // Limite à 2000 caractères
    }
  };
});
